#!/usr/bin/env python3
"""Generates port/mutations-authority.json: one deliberate defect per behaviour of the approval-dialog half of src/authority
(auth_*.go, uiprompt.go). Each `find` must occur exactly once in its file (checked here). Run with
  pigeq mutate --unit-only --go extensions/pi-permission-system --mutations port/mutations-authority.json --sdk-dir $PIG_SDK_DIR --jobs 4
from components/permissions."""
import json, os

root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "extensions", "pi-permission-system")
M = []

def m(name, file, find, replace):
    M.append({"name": name, "file": file, "find": find, "replace": replace})

