bad = 0
for x in M:
    src = open(os.path.join(root, x["file"])).read()
    n = src.count(x["find"])
    if n != 1:
        print("find occurs %d times: %s (%s)" % (n, x["name"], x["file"]))
        bad += 1
    elif x["find"] == x["replace"]:
        print("no-op mutation: %s" % x["name"])
        bad += 1
if len({x["name"] for x in M}) != len(M):
    print("duplicate names"); bad += 1
if bad:
    raise SystemExit(1)
here = os.path.dirname(os.path.abspath(__file__))
json.dump(M, open(os.path.join(here, "mutations-authority.json"), "w"), indent=1, ensure_ascii=False)
open(os.path.join(here, "mutations-authority.json"), "a").write("\n")
print(len(M), "mutations")
